@utility border-brutal {
  border: 1px solid var(--primary);
}

@layer components {
  /*
   * SSR-safe scroll motion: content stays visible until JS enables motion.
   * Fades + subtle zoom in/out as sections enter and leave the viewport.
   */
  html.scroll-motion-enabled .scroll-motion {
    opacity: 0;
    transform: scale(0.97);
    transition:
      opacity 0.65s cubic-bezier(0.16, 1, 0.3, 1),
      transform 0.65s cubic-bezier(0.16, 1, 0.3, 1);
    will-change: opacity, transform;
  }

  html.scroll-motion-enabled .scroll-motion.is-in-view {
    opacity: 1;
    transform: scale(1);
  }

  @media (prefers-reduced-motion: reduce) {
    html.scroll-motion-enabled .scroll-motion {
      opacity: 1;
      transform: none;
      transition: none;
      will-change: auto;
    }
  }
}

