import { flyComponentRegistry, type FlyBuildMode } from "../../../pietersoudan-config";

export type FlyDeployEnvironment = "staging";

export type FlyDeployAppCategory = "api" | "frontend";

export type FlyDeployCatalogEntry = {
  readonly key: string;
  readonly label: string;
  readonly category: FlyDeployAppCategory;
  readonly buildMode: FlyBuildMode;
  readonly flyAppName: string;
  readonly hint: string;
  readonly deployOrder: number;
};

export type FlyDeployCatalog = {
  readonly environment: FlyDeployEnvironment;
  readonly environmentLabel: string;
  readonly entries: readonly FlyDeployCatalogEntry[];
  readonly deployOrder: readonly string[];
};

export const flyDeployEnvironments = {
  staging: {
    label: "Staging",
    hint: "Current Fly staging apps",
  },
} as const satisfies Record<
  FlyDeployEnvironment,
  { readonly label: string; readonly hint: string }
>;

const labelByKey: Record<string, string> = {
  landing: "Portfolio landing",
};

const categoryByKey: Record<string, FlyDeployAppCategory> = {
  landing: "frontend",
};

const buildModeHint = (buildMode: FlyBuildMode): string => {
  switch (buildMode) {
    case "none":
      return "Docker/Fly build";
    case "vite-static":
      return "Vite static build";
    case "tanstack-static":
      return "TanStack Start prerender";
  }
};

export function getFlyDeployCatalog(
  environment: FlyDeployEnvironment = "staging",
): FlyDeployCatalog {
  const deployOrderIndex = new Map(
    flyComponentRegistry.deployOrder.map((key, index) => [key, index]),
  );

  return {
    environment,
    environmentLabel: flyDeployEnvironments[environment].label,
    deployOrder: flyComponentRegistry.deployOrder,
    entries: flyComponentRegistry.components
      .map((component): FlyDeployCatalogEntry => {
        const deployOrder = deployOrderIndex.get(component.key) ?? 999;
        return {
          key: component.key,
          label: labelByKey[component.key] ?? component.key,
          category: categoryByKey[component.key] ?? "frontend",
          buildMode: component.buildMode,
          flyAppName: component.appName,
          hint: `${component.appName} • ${buildModeHint(component.buildMode)}`,
          deployOrder,
        };
      })
      .sort((left, right) => left.deployOrder - right.deployOrder),
  };
}

export function sortCatalogKeysByDeployOrder(
  keys: readonly string[],
  catalog: FlyDeployCatalog,
): readonly string[] {
  const orderIndex = new Map(catalog.deployOrder.map((key, index) => [key, index]));
  return [...keys].sort(
    (left, right) => (orderIndex.get(left) ?? 999) - (orderIndex.get(right) ?? 999),
  );
}

export function getCatalogEntriesForKeys(
  keys: readonly string[],
  catalog: FlyDeployCatalog,
): readonly FlyDeployCatalogEntry[] {
  const byKey = new Map(catalog.entries.map((entry) => [entry.key, entry]));
  return keys
    .map((key) => byKey.get(key))
    .filter((entry): entry is FlyDeployCatalogEntry => Boolean(entry));
}

import { Effect, Option } from "effect";
import { getFlyDeployCatalog, sortCatalogKeysByDeployOrder } from "./fly-deploy-catalog.js";
import { runFlyCommand } from "./fly-operations-service.js";
import {
  promptDeployConfirm,
  promptDeployEnvironment,
  promptDeployTargets,
} from "../ui/deploy-prompts.js";
import { createOpsUI, isInteractiveTerminal } from "../ui/ops-ui.js";

export type RunInteractiveFlyDeployOptions = {
  readonly flyArgs?: string;
};

export function runInteractiveFlyDeploy(
  options: RunInteractiveFlyDeployOptions,
): Effect.Effect<void, Error> {
  return Effect.tryPromise({
    try: async () => {
      const ui = createOpsUI();
      ui.intro("Pieter Soudan deploy");

      const environment = await promptDeployEnvironment();
      const catalog = getFlyDeployCatalog(environment);
      const selectedKeys = await promptDeployTargets(catalog);
      const orderedKeys = sortCatalogKeysByDeployOrder(selectedKeys, catalog);
      const confirmed = await promptDeployConfirm(catalog, orderedKeys);

      if (!confirmed) {
        ui.cancelled();
        return;
      }

      await Effect.runPromise(
        runFlyCommand({
          action: "deploy",
          environment,
          flyArgs: options.flyArgs,
          targets: orderedKeys.join(","),
        }),
      );

      ui.outro(`Deployed ${orderedKeys.length} application(s) to ${catalog.environmentLabel}.`);
    },
    catch: (error) => (error instanceof Error ? error : new Error(String(error))),
  });
}

export function shouldRunInteractiveDeploy(input: {
  readonly environment: Option.Option<string>;
  readonly nonInteractive: boolean;
  readonly targets: string;
}): boolean {
  if (input.nonInteractive) {
    return false;
  }
  if (!isInteractiveTerminal()) {
    return false;
  }
  if (input.targets.trim() !== "all") {
    return false;
  }
  if (Option.isSome(input.environment)) {
    return false;
  }
  return true;
}

import { cancel, confirm, isCancel, multiselect, note, select } from "@clack/prompts";
import chalk from "chalk";
import Table from "cli-table3";
import {
  flyDeployEnvironments,
  getCatalogEntriesForKeys,
  type FlyDeployAppCategory,
  type FlyDeployCatalog,
  type FlyDeployEnvironment,
} from "../services/fly-deploy-catalog.js";

let hasShownMultiselectHelp = false;

function showMultiselectHelpOnce(): void {
  if (hasShownMultiselectHelp) {
    return;
  }
  note(
    "Use up/down to navigate, Space to select/deselect, Enter to confirm, a to toggle all.",
    "Keyboard shortcuts",
  );
  hasShownMultiselectHelp = true;
}

function categoryPrefix(category: FlyDeployAppCategory): string {
  switch (category) {
    case "api":
      return "API";
    case "frontend":
      return "Frontend";
  }
}

export async function promptDeployEnvironment(): Promise<FlyDeployEnvironment> {
  const value = await select<FlyDeployEnvironment>({
    message: "Which environment should be deployed?",
    options: [
      {
        value: "staging",
        label: flyDeployEnvironments.staging.label,
        hint: flyDeployEnvironments.staging.hint,
      },
    ],
    initialValue: "staging",
  });

  if (isCancel(value)) {
    cancel("Deploy cancelled.");
    process.exit(0);
  }

  return value;
}

export async function promptDeployTargets(catalog: FlyDeployCatalog): Promise<string[]> {
  const allKeys = catalog.entries.map((entry) => entry.key);

  const selectionMode = await select<"all" | "pick">({
    message: "Which applications should be deployed?",
    options: [
      {
        value: "all",
        label: "All applications",
        hint: "Pre-select registered Fly apps",
      },
      {
        value: "pick",
        label: "Choose individually",
        hint: "Start with nothing selected",
      },
    ],
    initialValue: "all",
  });

  if (isCancel(selectionMode)) {
    cancel("Deploy cancelled.");
    process.exit(0);
  }

  showMultiselectHelpOnce();

  const value = await multiselect<string>({
    message:
      selectionMode === "all"
        ? "Confirm applications (Space to deselect items to skip)"
        : "Select applications to deploy",
    options: catalog.entries.map((entry) => ({
      value: entry.key,
      label: `[${categoryPrefix(entry.category)}] ${entry.label}`,
      hint: entry.hint,
    })),
    initialValues: selectionMode === "all" ? allKeys : [],
    required: true,
  });

  if (isCancel(value)) {
    cancel("Deploy cancelled.");
    process.exit(0);
  }

  if (value.length === 0) {
    throw new Error("Select at least one application to deploy.");
  }

  return value;
}

export function renderDeployPlanTable(
  catalog: FlyDeployCatalog,
  orderedKeys: readonly string[],
): string {
  const entries = getCatalogEntriesForKeys(orderedKeys, catalog);
  const table = new Table({
    head: [chalk.cyan("#"), chalk.cyan("Application"), chalk.cyan("Build"), chalk.cyan("Fly app")],
  });

  entries.forEach((entry, index) => {
    table.push([String(index + 1), entry.label, entry.buildMode, entry.flyAppName]);
  });

  return table.toString();
}

export async function promptDeployConfirm(
  catalog: FlyDeployCatalog,
  orderedKeys: readonly string[],
): Promise<boolean> {
  note(
    [
      chalk.bold(`Pieter Soudan — ${catalog.environmentLabel}`),
      "",
      renderDeployPlanTable(catalog, orderedKeys),
    ]
      .filter(Boolean)
      .join("\n"),
    "Deploy plan",
  );

  const value = await confirm({
    message: `Deploy ${orderedKeys.length} application(s) now?`,
    initialValue: true,
  });

  if (isCancel(value)) {
    cancel("Deploy cancelled.");
    process.exit(0);
  }

  return value;
}

import { intro, outro } from "@clack/prompts";
import chalk from "chalk";

export function isInteractiveTerminal(): boolean {
  return Boolean(process.stdin.isTTY && process.stdout.isTTY);
}

export function createOpsUI() {
  return {
    intro(title: string) {
      intro(chalk.cyan(title));
    },
    outro(message: string) {
      outro(chalk.green(message));
    },
    cancelled(message = "Deploy cancelled.") {
      outro(chalk.yellow(message));
    },
  };
}

import { Argument, Command, Flag } from "effect/unstable/cli";
import { Option } from "effect";
import {
  parseFlyDeployEnvironment,
  runFlyCommand,
  type FlyAction,
} from "../services/fly-operations-service.js";
import {
  runInteractiveFlyDeploy,
  shouldRunInteractiveDeploy,
} from "../services/fly-interactive-deploy-service.js";

const flyDeployFlags = {
  targets: Argument.string("targets").pipe(Argument.withDefault("all")),
  flyArgs: Flag.optional(
    Flag.string("fly-args").pipe(
      Flag.withDescription(
        "Optional extra Fly arguments as a space-separated string, for example '--remote-only'",
      ),
    ),
  ),
  environment: Flag.optional(
    Flag.string("environment").pipe(
      Flag.withDescription("Deploy environment. Only staging is supported for now."),
    ),
  ),
  nonInteractive: Flag.boolean("non-interactive").pipe(
    Flag.withDescription("Skip the interactive picker and deploy using targets and flags."),
    Flag.withDefault(false),
  ),
} as const;

function resolveFlyCommandOptions(
  action: FlyAction,
  input: {
    environment: Option.Option<string>;
    flyArgs: Option.Option<string>;
    targets: string;
  },
) {
  return {
    action,
    environment: Option.isSome(input.environment)
      ? parseFlyDeployEnvironment(input.environment.value)
      : undefined,
    flyArgs: Option.isSome(input.flyArgs) ? input.flyArgs.value : undefined,
    targets: input.targets,
  };
}

export const flyDeployCommand = Command.make(
  "deploy",
  flyDeployFlags,
  ({ environment, flyArgs, nonInteractive, targets }) => {
    if (shouldRunInteractiveDeploy({ environment, nonInteractive, targets })) {
      return runInteractiveFlyDeploy({
        flyArgs: Option.isSome(flyArgs) ? flyArgs.value : undefined,
      });
    }

    return runFlyCommand(resolveFlyCommandOptions("deploy", { environment, flyArgs, targets }));
  },
).pipe(
  Command.withDescription(
    "Build and deploy Fly components. Interactive by default on a TTY; pass --non-interactive with targets and flags for scripts and CI.",
  ),
);

function makeFlyActionCommand(action: FlyAction, description: string) {
  return Command.make(
    action,
    {
      targets: flyDeployFlags.targets,
      environment: flyDeployFlags.environment,
      flyArgs: flyDeployFlags.flyArgs,
    },
    ({ environment, flyArgs, targets }) =>
      runFlyCommand(resolveFlyCommandOptions(action, { environment, flyArgs, targets })),
  ).pipe(Command.withDescription(description));
}

export const flyLogsCommand = makeFlyActionCommand(
  "logs",
  "Show Fly logs for one or more components.",
);

export const flyStatusCommand = makeFlyActionCommand(
  "status",
  "Show Fly status for one or more components.",
);

export const flyOpenCommand = makeFlyActionCommand(
  "open",
  "Open one or more Fly apps in the browser.",
);

export const flySshCommand = makeFlyActionCommand(
  "ssh",
  "Open a Fly SSH console for one or more components.",
);

export const flyMachinesCommand = makeFlyActionCommand(
  "machines",
  "List Fly machines for one or more components.",
);

export const flyCommand = Command.make("fly").pipe(
  Command.withSubcommands([
    flyDeployCommand,
    flyLogsCommand,
    flyStatusCommand,
    flyOpenCommand,
    flySshCommand,
    flyMachinesCommand,
  ]),
  Command.withDescription("Fly.io deployment and operational tasks."),
);

