import { useLayoutEffect, useRef } from "react";

type HeadlineRolesProps = {
  readonly roles: readonly string[];
};

function markLineStarts(container: HTMLElement) {
  const items = [...container.children].filter(
    (node): node is HTMLSpanElement => node instanceof HTMLSpanElement,
  );

  let previousTop: number | null = null;

  for (const item of items) {
    const top = item.offsetTop;
    const isLineStart = previousTop !== null && top > previousTop;
    item.classList.toggle("line-start", isLineStart);
    previousTop = top;
  }
}

export function HeadlineRoles({ roles }: HeadlineRolesProps) {
  const containerRef = useRef<HTMLParagraphElement>(null);

  useLayoutEffect(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }

    const update = () => {
      markLineStarts(container);
    };

    update();

    const observer = new ResizeObserver(update);
    observer.observe(container);

    for (const item of container.children) {
      observer.observe(item);
    }

    window.addEventListener("resize", update, { passive: true });

    return () => {
      observer.disconnect();
      window.removeEventListener("resize", update);
    };
  }, [roles]);

  return (
    <p ref={containerRef} className="font-label-mono headline-roles mb-4 text-foreground">
      {roles.map((role) => (
        <span key={role}>{role}</span>
      ))}
    </p>
  );
}

