export type ShaderBackgroundVariant = "grid-light" | "grid-dark" | "scanline-grid";

export const VERTEX_SHADER = `attribute vec2 a_position;
varying vec2 v_texCoord;
void main() {
  v_texCoord = a_position * 0.5 + 0.5;
  gl_Position = vec4(a_position, 0.0, 1.0);
}`;

/** Stitch ANIMATION_5 — subtle architectural grid on a light field. */
export const GRID_LIGHT_FRAGMENT = `precision highp float;
uniform float u_time;
uniform vec2 u_resolution;
uniform vec2 u_mouse;
varying vec2 v_texCoord;

void main() {
  vec2 uv = v_texCoord;
  vec2 mouse = u_mouse / u_resolution;

  float grid = sin(uv.x * 50.0) * sin(uv.y * 50.0);
  grid = smoothstep(0.98, 1.0, grid);

  float line = sin(uv.y * 100.0 + u_time * 2.0) * 0.02;
  float dist = length(uv - mouse);
  float glow = smoothstep(0.2, 0.0, dist) * 0.05;

  vec3 color = vec3(0.98);
  color -= grid * 0.03;
  color += line;
  color += glow;

  gl_FragColor = vec4(color, 1.0);
}`;

/** Dark inverse — white grid lines and scanlines on black (values band). */
export const GRID_DARK_FRAGMENT = `precision highp float;
uniform float u_time;
uniform vec2 u_resolution;
uniform vec2 u_mouse;
varying vec2 v_texCoord;

void main() {
  vec2 uv = v_texCoord;
  vec2 mouse = u_mouse / u_resolution;

  float grid = sin(uv.x * 50.0) * sin(uv.y * 50.0);
  grid = smoothstep(0.98, 1.0, grid);

  float line = sin(uv.y * 100.0 + u_time * 1.6) * 0.015;
  float dist = length(uv - mouse);
  float glow = smoothstep(0.22, 0.0, dist) * 0.07;

  vec3 color = vec3(0.0);
  color += grid * 0.055;
  color += line;
  color += glow;

  gl_FragColor = vec4(color, 1.0);
}`;

/** Emphasised scanline grid for full-bleed focus bands. */
export const SCANLINE_GRID_FRAGMENT = `precision highp float;
uniform float u_time;
uniform vec2 u_resolution;
uniform vec2 u_mouse;
varying vec2 v_texCoord;

void main() {
  vec2 uv = v_texCoord;
  vec2 pixel = uv * u_resolution;
  vec2 mouse = u_mouse / u_resolution;

  float gridX = smoothstep(0.985, 1.0, sin(pixel.x * 3.14159265 / 50.0));
  float gridY = smoothstep(0.985, 1.0, sin(pixel.y * 3.14159265 / 50.0));
  float grid = max(gridX, gridY);

  float scan = sin(uv.y * 120.0 + u_time * 2.4) * 0.012;
  float sweep = sin(uv.x * 8.0 - u_time * 0.35) * 0.008;
  float dist = length(uv - mouse);
  float glow = smoothstep(0.25, 0.0, dist) * 0.04;

  vec3 color = vec3(0.0);
  color += grid * 0.07;
  color += scan + sweep;
  color += glow;

  gl_FragColor = vec4(color, 1.0);
}`;

export const FRAGMENT_SHADERS: Record<ShaderBackgroundVariant, string> = {
  "grid-light": GRID_LIGHT_FRAGMENT,
  "grid-dark": GRID_DARK_FRAGMENT,
  "scanline-grid": SCANLINE_GRID_FRAGMENT,
};

export const SHADER_FALLBACK_CLASS: Record<ShaderBackgroundVariant, string> = {
  "grid-light": "shader-fallback-grid-light",
  "grid-dark": "shader-fallback-grid-dark",
  "scanline-grid": "shader-fallback-scanline-grid",
};

import { useEffect, useRef, type RefObject } from "react";

import {
  FRAGMENT_SHADERS,
  VERTEX_SHADER,
  type ShaderBackgroundVariant,
} from "#/components/shader-background/shaders";

type UseShaderCanvasOptions = {
  readonly canvasRef: RefObject<HTMLCanvasElement | null>;
  readonly variant: ShaderBackgroundVariant;
  readonly active?: boolean;
  readonly trackMouse?: boolean;
};

function compileShader(gl: WebGLRenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) {
    return null;
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

function createProgram(gl: WebGLRenderingContext, fragmentSource: string) {
  const vertexShader = compileShader(gl, gl.VERTEX_SHADER, VERTEX_SHADER);
  const fragmentShader = compileShader(gl, gl.FRAGMENT_SHADER, fragmentSource);
  if (!vertexShader || !fragmentShader) {
    return null;
  }

  const program = gl.createProgram();
  if (!program) {
    return null;
  }

  gl.attachShader(program, vertexShader);
  gl.attachShader(program, fragmentShader);
  gl.linkProgram(program);

  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }

  return program;
}

export function useShaderCanvas({
  canvasRef,
  variant,
  active = true,
  trackMouse = true,
}: UseShaderCanvasOptions) {
  const supportsWebGlRef = useRef(true);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !active) {
      return;
    }

    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reducedMotion) {
      supportsWebGlRef.current = false;
      return;
    }

    const gl = canvas.getContext("webgl", { alpha: true, antialias: false });
    if (!gl) {
      supportsWebGlRef.current = false;
      return;
    }

    const program = createProgram(gl, FRAGMENT_SHADERS[variant]);
    if (!program) {
      supportsWebGlRef.current = false;
      return;
    }

    gl.useProgram(program);

    const buffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(
      gl.ARRAY_BUFFER,
      new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]),
      gl.STATIC_DRAW,
    );

    const positionLocation = gl.getAttribLocation(program, "a_position");
    gl.enableVertexAttribArray(positionLocation);
    gl.vertexAttribPointer(positionLocation, 2, gl.FLOAT, false, 0, 0);

    const timeLocation = gl.getUniformLocation(program, "u_time");
    const resolutionLocation = gl.getUniformLocation(program, "u_resolution");
    const mouseLocation = gl.getUniformLocation(program, "u_mouse");

    const mouse = { x: canvas.width / 2, y: canvas.height / 2 };

    const syncSize = () => {
      const width = canvas.clientWidth || 1;
      const height = canvas.clientHeight || 1;
      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
      }
    };

    syncSize();

    const resizeObserver =
      typeof ResizeObserver !== "undefined" ? new ResizeObserver(syncSize) : null;
    resizeObserver?.observe(canvas);

    const onMouseMove = (event: MouseEvent) => {
      if (!trackMouse) {
        return;
      }
      const rect = canvas.getBoundingClientRect();
      if (rect.width <= 0 || rect.height <= 0) {
        return;
      }
      const normalizedX = (event.clientX - rect.left) / rect.width;
      const normalizedY = 1 - (event.clientY - rect.top) / rect.height;
      mouse.x = normalizedX * canvas.width;
      mouse.y = normalizedY * canvas.height;
    };

    if (trackMouse) {
      window.addEventListener("mousemove", onMouseMove, { passive: true });
    }

    let frameId = 0;
    let running = true;

    const render = (time: number) => {
      if (!running) {
        return;
      }
      syncSize();
      gl.viewport(0, 0, canvas.width, canvas.height);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);

      if (timeLocation) {
