    return () => {
      running = false;
      window.cancelAnimationFrame(frameId);
      resizeObserver?.disconnect();
      if (trackMouse) {
        window.removeEventListener("mousemove", onMouseMove);
      }
      gl.deleteProgram(program);
      if (buffer) {
        gl.deleteBuffer(buffer);
      }
